INF = float("inf")
buckets = [(0.05, 600), (0.1, 900), (0.25, 960), (0.5, 990), (1.0, 998), (INF, 1000)]  # (le, 누적 개수)

def hq(q, b):
    rank = q * b[-1][1]
    prev_le, prev_c = 0.0, 0
    for le, c in b:
        if c >= rank:
            if le == INF:
                return prev_le
            return prev_le + (le - prev_le) * (rank - prev_c) / (c - prev_c)
        prev_le, prev_c = le, c

for q in (0.5, 0.95, 0.99):
    print(f"p{int(q * 100)} = {hq(q, buckets) * 1000:.0f}ms")
# p50 = 42ms
# p95 = 225ms
# p99 = 500ms
